#!/usr/bin/env bash
# ==============================================================================
# install-lm-studio.sh
# 
# Installer & In-Place Updater utility for LM Studio on Fedora Linux
# (KDE Plasma & Freedesktop compliant).
# 
# Generated by: Antigravity AI Assistant (Google DeepMind)
# Model: Gemini 3.8 Flash
# Date: October 2026
# SPDX-License-Identifier: MIT
# License: MIT (see LICENSE)
# ==============================================================================

set -euo pipefail

# Text formatting
BOLD="\033[1m"
GREEN="\033[32m"
BLUE="\033[34m"
YELLOW="\033[33m"
RED="\033[31m"
RESET="\033[0m"

log_info()  { echo -e "${BLUE}${BOLD}[INFO]${RESET} $*"; }
log_ok()    { echo -e "${GREEN}${BOLD}[OK]${RESET} $*"; }
log_warn()  { echo -e "${YELLOW}${BOLD}[WARN]${RESET} $*"; }
log_error() { echo -e "${RED}${BOLD}[ERROR]${RESET} $*" >&2; }

# Defaults
# Note: LM Studio stores downloaded models in ~/.lmstudio and cache files in
# ~/.cache/lm-studio. We install the application into ~/.local/share/lm-studio
# so all models and user configurations remain 100% safe during updates.
DEFAULT_DEST_DIR="${HOME}/.local/share/lm-studio"
DEFAULT_BIN_DIR="${HOME}/.local/bin"
APP_NAME="LM Studio"
DESKTOP_ID="lm-studio"
STARTUP_WM_CLASS="ai.elementlabs.lmstudio"

DEST_DIR="${DEFAULT_DEST_DIR}"
BIN_DIR="${DEFAULT_BIN_DIR}"
CUSTOM_ICON=""
APPIMAGE_PATH=""
DO_UNINSTALL=false

show_help() {
    echo -e "${BOLD}LM Studio Installer & In-Place Updater for Fedora Linux (KDE Plasma)${RESET}

Usage:
  $(basename "$0") [OPTIONS] [PATH_TO_APPIMAGE]

Options:
  -d, --dest <DIR>       Destination directory for application files
                         (default: ${DEFAULT_DEST_DIR})
  -b, --bin-dir <DIR>    Directory for terminal launcher command(s)
                         (default: ${DEFAULT_BIN_DIR})
  -i, --icon <PATH>      Custom application icon (.png or .svg).
                         If omitted, automatically extracts the official high-resolution
                         icons (16x16 to 512x512) directly from the AppImage.
  -u, --uninstall        Remove LM Studio application files, desktop entry,
                         icons, and terminal launchers. Downloaded models in
                         ~/.lmstudio and ~/.cache/lm-studio remain completely intact.
  -h, --help             Show this help message and exit.

Examples:
  # Install using an explicit AppImage path:
  $(basename "$0") ~/Downloads/LM-Studio-0.4.26-4-x64.AppImage

  # Install using automatic detection from ~/Downloads or current dir:
  $(basename "$0")

  # Install with a custom icon:
  $(basename "$0") --icon ~/Pictures/my-icon.png

  # Uninstall:
  $(basename "$0") --uninstall"
}

# Parse options
while [[ $# -gt 0 ]]; do
    case "$1" in
        -h|--help)
            show_help
            exit 0
            ;;
        -d|--dest)
            DEST_DIR="$(realpath -m "$2")"
            shift 2
            ;;
        -b|--bin-dir)
            BIN_DIR="$(realpath -m "$2")"
            shift 2
            ;;
        -i|--icon)
            CUSTOM_ICON="$(realpath "$2")"
            shift 2
            ;;
        -u|--uninstall)
            DO_UNINSTALL=true
            shift
            ;;
        -*)
            log_error "Unknown option: $1"
            show_help
            exit 1
            ;;
        *)
            if [[ -z "${APPIMAGE_PATH}" ]]; then
                APPIMAGE_PATH="$(realpath "$1")"
            else
                log_error "Unexpected argument: $1"
                exit 1
            fi
            shift
            ;;
    esac
done

# ------------------------------------------------------------------------------
# Refresh desktop and icon databases
# ------------------------------------------------------------------------------
refresh_system_caches() {
    log_info "Updating system icon and desktop entry caches..."

    if command -v gtk-update-icon-cache >/dev/null 2>&1; then
        gtk-update-icon-cache -f -t "${HOME}/.local/share/icons/hicolor" 2>/dev/null || true
    fi

    if command -v update-desktop-database >/dev/null 2>&1; then
        update-desktop-database "${HOME}/.local/share/applications" 2>/dev/null || true
    fi

    # KDE Plasma Sycoca cache refresh (Plasma 6 / Plasma 5)
    if command -v kbuildsycoca6 >/dev/null 2>&1; then
        kbuildsycoca6 2>/dev/null || true
    elif command -v kbuildsycoca5 >/dev/null 2>&1; then
        kbuildsycoca5 2>/dev/null || true
    fi
}

# ------------------------------------------------------------------------------
# Version detection helper
# ------------------------------------------------------------------------------
get_app_version() {
    local target_appimage="$1"
    local ver=""

    if [[ -x "${target_appimage}" ]]; then
        # Fast extraction of desktop entry from AppImage
        local temp_ver_dir
        temp_ver_dir="$(mktemp -d -t lm-studio-ver-XXXXXX)"
        if ( cd "${temp_ver_dir}" && "${target_appimage}" --appimage-extract "*.desktop" >/dev/null 2>&1 ); then
            local desktop_cand
            desktop_cand="$(find "${temp_ver_dir}/squashfs-root" -maxdepth 2 -name "*.desktop" 2>/dev/null | head -n 1)"
            if [[ -n "${desktop_cand}" && -f "${desktop_cand}" ]]; then
                ver="$(grep -m1 '^X-AppImage-Version=' "${desktop_cand}" 2>/dev/null | cut -d'=' -f2- | tr -d '\r\n' || true)"
            fi
        fi
        rm -rf "${temp_ver_dir}"
    fi

    # Fallback to filename parsing if internal desktop entry didn't provide version
    if [[ -z "${ver}" && -n "${target_appimage}" ]]; then
        local base
        base="$(basename "${target_appimage}")"
        # Matches e.g. LM-Studio-0.4.26-4-x64.AppImage or LM_Studio-0.4.26.AppImage
        if [[ "${base}" =~ [Ll][Mm][-_\ ]?[Ss]tudio[-_]v?([0-9]+(\.[0-9]+)*(-[a-zA-Z0-9._+]+)?) ]]; then
            ver="${BASH_REMATCH[1]}"
        fi
    fi

    if [[ -z "${ver}" ]]; then
        ver="unknown"
    fi
    echo "${ver}"
}

# ------------------------------------------------------------------------------
# Uninstall Routine
# ------------------------------------------------------------------------------
if [[ "${DO_UNINSTALL}" == "true" ]]; then
    log_info "Starting uninstallation of LM Studio..."

    # Remove application directory
    if [[ -d "${DEST_DIR}" ]]; then
        rm -rf "${DEST_DIR}"
        log_ok "Removed application directory: ${DEST_DIR}"
    fi

    # Remove terminal binaries / launchers
    for launcher in "${DESKTOP_ID}" "lmstudio"; do
        if [[ -f "${BIN_DIR}/${launcher}" || -L "${BIN_DIR}/${launcher}" ]]; then
            rm -f "${BIN_DIR}/${launcher}"
            log_ok "Removed terminal launcher: ${BIN_DIR}/${launcher}"
        fi
    done

    # Remove desktop entry
    for desktop_name in "${DESKTOP_ID}.desktop" "${STARTUP_WM_CLASS}.desktop"; do
        DESKTOP_FILE="${HOME}/.local/share/applications/${desktop_name}"
        if [[ -f "${DESKTOP_FILE}" ]]; then
            rm -f "${DESKTOP_FILE}"
            log_ok "Removed desktop entry: ${DESKTOP_FILE}"
        fi
    done

    # Remove installed icons from hicolor theme
    ICON_BASE="${HOME}/.local/share/icons/hicolor"
    for size in 16x16 24x24 32x32 48x48 64x64 128x128 256x256 512x512 scalable; do
        for ext in png svg; do
            for name in "${DESKTOP_ID}" "${STARTUP_WM_CLASS}"; do
                target="${ICON_BASE}/${size}/apps/${name}.${ext}"
                if [[ -f "${target}" || -L "${target}" ]]; then
                    rm -f "${target}"
                fi
            done
        done
    done
    rm -f "${HOME}/.local/share/pixmaps/${DESKTOP_ID}.png" 2>/dev/null || true
    rm -f "${HOME}/.local/share/pixmaps/${STARTUP_WM_CLASS}.png" 2>/dev/null || true
    log_ok "Removed desktop icons"

    refresh_system_caches

    log_info "Note: Downloaded models and local settings in ~/.lmstudio and ~/.cache/lm-studio were kept safe and untouched."
    log_ok "LM Studio uninstalled successfully."
    exit 0
fi

# ------------------------------------------------------------------------------
# AppImage Resolution
# ------------------------------------------------------------------------------
if [[ -z "${APPIMAGE_PATH}" ]]; then
    log_info "No AppImage path provided. Checking current directory and ~/Downloads..."
    # Find AppImages and sort by modification timestamp (newest first)
    NEWEST_APPIMAGE="$(find . "${HOME}/Downloads" -maxdepth 1 \( -iname "*lm*studio*.appimage" -o -iname "*lmstudio*.appimage" \) -printf '%T@ %p\n' 2>/dev/null | sort -nr | head -n 1 | cut -d' ' -f2-)"

    if [[ -n "${NEWEST_APPIMAGE}" && -f "${NEWEST_APPIMAGE}" ]]; then
        APPIMAGE_PATH="${NEWEST_APPIMAGE}"
        log_info "Auto-detected most recently downloaded AppImage: ${APPIMAGE_PATH}"
    else
        log_error "Could not find an LM Studio .AppImage in current directory or ~/Downloads."
        log_error "Please specify the path: $(basename "$0") /path/to/LM-Studio-x.x.x-x64.AppImage"
        exit 1
    fi
fi

if [[ ! -f "${APPIMAGE_PATH}" ]]; then
    log_error "AppImage file not found: ${APPIMAGE_PATH}"
    exit 1
fi

# Ensure executable permissions on source AppImage for inspection/extraction
chmod +x "${APPIMAGE_PATH}" 2>/dev/null || true

# Verify it is an ELF binary / AppImage
if ! head -c 4 "${APPIMAGE_PATH}" | grep -q $'\x7fELF'; then
    log_error "The specified file is not a valid ELF executable / AppImage: ${APPIMAGE_PATH}"
    exit 1
fi

# Check required system utilities
for tool in realpath mktemp find cut grep; do
    if ! command -v "${tool}" >/dev/null 2>&1; then
        log_error "Required utility '${tool}' is not installed."
        exit 1
    fi
done

# Check if application is currently running
if pgrep -i "^(lm-studio|lmstudio)" >/dev/null 2>&1; then
    log_warn "LM Studio appears to be currently running."
    log_warn "If you experience issues, please close LM Studio before updating."
fi

# Detect currently installed version if updating
OLD_VERSION="none"
INSTALLED_DESKTOP="${HOME}/.local/share/applications/${DESKTOP_ID}.desktop"
if [[ -f "${INSTALLED_DESKTOP}" ]]; then
    OLD_VERSION="$(grep -m1 '^X-AppImage-Version=' "${INSTALLED_DESKTOP}" 2>/dev/null | cut -d'=' -f2- | tr -d '\r\n' || echo "none")"
fi
if [[ -z "${OLD_VERSION}" || "${OLD_VERSION}" == "none" ]] && [[ -x "${DEST_DIR}/lm-studio" ]]; then
    OLD_VERSION="$(get_app_version "${DEST_DIR}/lm-studio")"
fi

# Determine new version
NEW_VERSION="$(get_app_version "${APPIMAGE_PATH}")"

# ------------------------------------------------------------------------------
# Icon Extraction & Configuration
# ------------------------------------------------------------------------------
log_info "Configuring application icons..."
ICON_BASE="${HOME}/.local/share/icons/hicolor"
ICON_NAME="${DESKTOP_ID}"
ICON_INFO=""

TEMP_EXTRACT_DIR="$(mktemp -d -t lm-studio-install-XXXXXX)"
cleanup() {
    rm -rf "${TEMP_EXTRACT_DIR}"
}
trap cleanup EXIT

if [[ -n "${CUSTOM_ICON}" ]]; then
    if [[ ! -f "${CUSTOM_ICON}" ]]; then
        log_error "Specified custom icon file not found: ${CUSTOM_ICON}"
        exit 1
    fi
    log_info "Installing custom icon: ${CUSTOM_ICON}"
    if [[ "${CUSTOM_ICON}" == *.svg ]]; then
        mkdir -p "${ICON_BASE}/scalable/apps"
        cp -f "${CUSTOM_ICON}" "${ICON_BASE}/scalable/apps/${DESKTOP_ID}.svg"
    else
        mkdir -p "${ICON_BASE}/512x512/apps"
        cp -f "${CUSTOM_ICON}" "${ICON_BASE}/512x512/apps/${DESKTOP_ID}.png"
    fi
    mkdir -p "${HOME}/.local/share/pixmaps"
    cp -f "${CUSTOM_ICON}" "${HOME}/.local/share/pixmaps/${DESKTOP_ID}.png" 2>/dev/null || true
    ICON_INFO="custom (${CUSTOM_ICON})"
    log_ok "Custom icon registered"
else
    log_info "Extracting official bundled icons from AppImage..."
    ( cd "${TEMP_EXTRACT_DIR}" && "${APPIMAGE_PATH}" --appimage-extract "usr/share/icons/*" >/dev/null 2>&1 ) || true

    FOUND_ICONS=0
    if [[ -d "${TEMP_EXTRACT_DIR}/squashfs-root/usr/share/icons/hicolor" ]]; then
        for size_dir in "${TEMP_EXTRACT_DIR}/squashfs-root/usr/share/icons/hicolor"/*; do
            if [[ -d "${size_dir}" ]]; then
                size="$(basename "${size_dir}")"
                for icon_file in "${size_dir}/apps"/*; do
                    if [[ -f "${icon_file}" ]]; then
                        mkdir -p "${ICON_BASE}/${size}/apps"
                        cp -f "${icon_file}" "${ICON_BASE}/${size}/apps/${DESKTOP_ID}.png"
                        FOUND_ICONS=$((FOUND_ICONS + 1))
                    fi
                done
            fi
        done
    fi

    # Pixmaps fallback
    if [[ -f "${ICON_BASE}/512x512/apps/${DESKTOP_ID}.png" ]]; then
        mkdir -p "${HOME}/.local/share/pixmaps"
        cp -f "${ICON_BASE}/512x512/apps/${DESKTOP_ID}.png" "${HOME}/.local/share/pixmaps/${DESKTOP_ID}.png"
    fi

    if [[ ${FOUND_ICONS} -gt 0 ]]; then
        log_ok "Extracted and installed ${FOUND_ICONS} official icon resolutions (hicolor 16x16 up to 512x512)"
        ICON_INFO="${ICON_NAME} (official bundled icons)"
    else
        log_warn "Could not extract icons from AppImage; checking system theme..."
        THEME_ICON_FOUND="$(find "${HOME}/.local/share/icons" "/usr/share/icons" -maxdepth 5 -type f \( -name "lm-studio.svg" -o -name "lm-studio.png" \) 2>/dev/null | head -n 1 || true)"
        if [[ -n "${THEME_ICON_FOUND}" ]]; then
            log_ok "Found theme icon: ${THEME_ICON_FOUND}"
            ICON_INFO="${ICON_NAME} (from system theme)"
        else
            log_warn "No icon found in system themes. Creating fallback SVG icon..."
            mkdir -p "${ICON_BASE}/scalable/apps"
            cat > "${ICON_BASE}/scalable/apps/${DESKTOP_ID}.svg" << 'EOF'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">
  <rect width="512" height="512" rx="110" fill="#1e1e2e"/>
  <rect x="96" y="96" width="320" height="320" rx="48" fill="#585b70" opacity="0.4"/>
  <path d="M160 352V160h48v144h80v48H160zm144 0V160h48l48 104 48-104h48v192h-44V224l-42 92h-20l-42-92v128h-46z" fill="#cdd6f4"/>
</svg>
EOF
            ICON_INFO="${ICON_NAME} (fallback SVG installed)"
        fi
    fi
fi

# ------------------------------------------------------------------------------
# AppImage Installation
# ------------------------------------------------------------------------------
log_info "Preparing destination directory: ${DEST_DIR}"
mkdir -p "${DEST_DIR}"

APPIMAGE_BASENAME="$(basename "${APPIMAGE_PATH}")"
TARGET_APPIMAGE="${DEST_DIR}/${APPIMAGE_BASENAME}"

# Clean up older AppImage builds in DEST_DIR to save disk space
while IFS= read -r old_file; do
    if [[ -f "${old_file}" && "$(basename "${old_file}")" != "${APPIMAGE_BASENAME}" ]]; then
        log_info "Removing older build: $(basename "${old_file}")..."
        rm -f "${old_file}"
    fi
done < <(find "${DEST_DIR}" -maxdepth 1 -type f \( -iname "*lm*studio*.appimage" -o -iname "*lmstudio*.appimage" \) 2>/dev/null)

log_info "Installing ${APPIMAGE_BASENAME} to ${DEST_DIR}..."
cp -f "${APPIMAGE_PATH}" "${TARGET_APPIMAGE}"
chmod +x "${TARGET_APPIMAGE}"

# Create stable symlinks inside DEST_DIR
ln -sfn "${APPIMAGE_BASENAME}" "${DEST_DIR}/lm-studio"
ln -sfn "${APPIMAGE_BASENAME}" "${DEST_DIR}/LM-Studio.AppImage"

# Also preserve a 512x512 icon inside DEST_DIR for easy reference
if [[ -f "${ICON_BASE}/512x512/apps/${DESKTOP_ID}.png" ]]; then
    cp -f "${ICON_BASE}/512x512/apps/${DESKTOP_ID}.png" "${DEST_DIR}/lm-studio.png"
fi

log_ok "AppImage installed successfully to ${TARGET_APPIMAGE}"

# ------------------------------------------------------------------------------
# Terminal Launcher Command
# ------------------------------------------------------------------------------
log_info "Configuring terminal command: ${BIN_DIR}/${DESKTOP_ID}"
mkdir -p "${BIN_DIR}"
LAUNCHER_SCRIPT="${BIN_DIR}/${DESKTOP_ID}"

cat > "${LAUNCHER_SCRIPT}" << EOF
#!/usr/bin/env bash
# LM Studio CLI Launcher
# Launch the LM Studio desktop application from terminal

APP_EXEC="${DEST_DIR}/lm-studio"

if [ ! -x "\$APP_EXEC" ]; then
    echo "Error: LM Studio executable not found at \$APP_EXEC" >&2
    exit 1
fi

exec "\$APP_EXEC" "\$@"
EOF

chmod +x "${LAUNCHER_SCRIPT}"
# Convenience alias symlink 'lmstudio' -> 'lm-studio'
ln -sfn "${DESKTOP_ID}" "${BIN_DIR}/lmstudio"
log_ok "Terminal launcher created: ${LAUNCHER_SCRIPT} (alias: ${BIN_DIR}/lmstudio)"

# Verify PATH
if [[ ":$PATH:" != *":${BIN_DIR}:"* ]]; then
    log_warn "'${BIN_DIR}' is not currently in your PATH environment variable."
    log_warn "Add the following line to your ~/.bashrc or ~/.zshrc:"
    log_warn "  export PATH=\"\$HOME/.local/bin:\$PATH\""
fi

# ------------------------------------------------------------------------------
# Desktop Entry
# ------------------------------------------------------------------------------
log_info "Creating KDE Plasma / Freedesktop desktop entry..."
APPLICATIONS_DIR="${HOME}/.local/share/applications"
mkdir -p "${APPLICATIONS_DIR}"
DESKTOP_FILE="${APPLICATIONS_DIR}/${DESKTOP_ID}.desktop"

cat > "${DESKTOP_FILE}" << EOF
[Desktop Entry]
Version=1.0
Type=Application
Name=${APP_NAME}
GenericName=Local LLM Development & Chat
Comment=Discover, download, and run local Large Language Models (LLMs)
Exec=${DEST_DIR}/lm-studio %U
Icon=${DESKTOP_ID}
Terminal=false
Categories=Development;Science;ArtificialIntelligence;
StartupWMClass=${STARTUP_WM_CLASS}
MimeType=x-scheme-handler/lmstudio;
Keywords=lmstudio;lm-studio;ai;llm;chat;models;local;server;llama;elementlabs;
StartupNotify=true
X-AppImage-Version=${NEW_VERSION}
EOF

chmod +x "${DESKTOP_FILE}"
log_ok "Desktop entry created: ${DESKTOP_FILE}"

# Refresh caches for KDE Plasma & GTK
refresh_system_caches

# ------------------------------------------------------------------------------
# Summary
# ------------------------------------------------------------------------------
echo ""
echo -e "${GREEN}${BOLD}═════════════════════════════════════════════════════════════════════${RESET}"
if [[ "${OLD_VERSION}" != "none" && "${OLD_VERSION}" != "unknown" && "${OLD_VERSION}" != "${NEW_VERSION}" ]]; then
    echo -e "${GREEN}${BOLD}   LM Studio has been successfully updated! (v${OLD_VERSION} -> v${NEW_VERSION})${RESET}"
else
    echo -e "${GREEN}${BOLD}   LM Studio (v${NEW_VERSION}) has been successfully installed!         ${RESET}"
fi
echo -e "${GREEN}${BOLD}═════════════════════════════════════════════════════════════════════${RESET}"
echo -e "  • ${BOLD}Version:${RESET}                ${NEW_VERSION}"
echo -e "  • ${BOLD}Application Directory:${RESET}  ${DEST_DIR}"
echo -e "  • ${BOLD}AppImage Target:${RESET}        ${TARGET_APPIMAGE}"
echo -e "  • ${BOLD}Terminal Command:${RESET}       ${BIN_DIR}/${DESKTOP_ID} (or 'lmstudio')"
echo -e "  • ${BOLD}Desktop Entry:${RESET}          ${DESKTOP_FILE}"
echo -e "  • ${BOLD}Application Icon:${RESET}       ${ICON_INFO}"
echo ""
echo -e "You can launch LM Studio from:"
echo -e "  1. KDE Application Launcher / KRunner (press ${BOLD}Alt+Space${RESET} and type ${BOLD}LM Studio${RESET})"
echo -e "  2. Terminal by typing: ${BOLD}lm-studio${RESET} or ${BOLD}lmstudio${RESET}"
echo ""
